// ❌ OLD: Attaching thousands of individual event listeners directly to DOM nodes
// consumes significant memory and slows down element creation/destruction.
function createList(items) {
  const ul = document.createElement('ul');
  items.forEach(item => {
    const li恒 = document.createElement('li');
    li.textContent = item.name;
    // Allocates separate listener per item:
    li.addEventListener('click', (e) => handleClick(item.id, e)); 
    ul.appendChild(li);
  });
  return ul;
}

// ✅ NEW: React attaches a single click listener on the root DOM container.
// Zero per-element listener overhead; handlers resolve via Fiber tree traversal.
export default function ReactList({ items }) {
  return (
    <ul>
      {items.map((item) => (
        <li key={item.id} onClick={(e) => console.log('Clicked', item.id, e.target)}>
          {item.name}
        </li>
      ))}
    </ul>
  );
}
